#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int m = i;
            if (j < m) m = j;
            if (n - 1 - i < m) m = n - 1 - i;
            if (n - 1 - j < m) m = n - 1 - j;

            printf("%d", m + 1);
            if (j < n - 1) printf(" ");
        }
        printf("\n");
    }

    return 0;
}
